package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamMediaCivilBank2 {
  private const val T = "ජනමාධ්‍ය, මහජන මතය, වැඩ ලෝකය හා සිවිල් සමාජය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("රජයෙන් හා වාණිජ ලාභ අපේක්ෂාවෙන් ස්වාධීනව පුරවැසියන් ස්වේච්ඡාවෙන් සංවිධානය වී පොදු යහපත උදෙසා ක්‍රියා කරන සමාජ අවකාශය කුමක්ද?", "සිවිල් සමාජය (Civil Society)", "හමුදා පාලනය", "මධ්‍යම අමාත්‍ය මණ්ඩලය", "විදේශ වෙළඳ කලාපය", "ප්‍රජා සමිති, වෘත්තීය සමිති, ස්වේච්ඡා සංවිධාන හා වෘත්තීය සංගම් සිවිල් සමාජයේ ප්‍රධාන කොටස් වේ."),
    q("ශ්‍රී ලංකාවේ ග්‍රාමීය මට්ටමින් ක්‍රියාත්මක වන 'මරණාධාර සමිති, කාන්තා සමිති සහ ගොවි සංවිධාන' අයත් වන්නේ කුමන සමාජ ආයතන වර්ගයටද?", "ප්‍රජා මූල සංවිධාන (CBOs - Community-Based Organizations)", "රාජ්‍ය සංස්ථා", "අභියාචනාධිකරණ", "ජාත්‍යන්තර බැංකු", "ගමේ ජනතාවගේ අන්‍යෝන්‍ය ආධාරයෙන් පවත්වාගෙන යන CBO ආයතන ශ්‍රී ලංකාවේ සිවිල් සමාජ ශක්තියයි."),
    q("රාජ්‍ය නොවන සංවිධාන (NGOs) ප්‍රජා සංවර්ධනය හා සමාජ සුබසාධනය උදෙසා ඉටු කරන ප්‍රධාන කාර්යය කුමක්ද?", "ආපදා සහන, අධ්‍යාපන ආධාර, මානව හිමිකම් දැනුවත් කිරීම් හා පරිසර සංරක්ෂණ ව්‍යාපෘති ක්‍රියාත්මක කිරීම", "නව ජාතික නීති පැනවීම", "බදු අය කිරීම", "මැතිවරණ පැවැත්වීම", "රජයේ සේවාවන්ට සහාය වෙමින් ආන්තික ප්‍රජාවන් නගා සිටුවීමට විනිවිදභාවයෙන් යුත් NGOs ක්‍රියා කරයි."),
    q("1958 දී ඒ.ටී. ආරියරත්න මහතාගේ මූලිකත්වයෙන් 'ශ්‍රමදාන' හා ස්වේච්ඡා සහයෝගීතාව මත ආරම්භ වූ ශ්‍රී ලාංකේය සිවිල් සමාජ ව්‍යාපාරය කුමක්ද?", "සර්වෝදය ශ්‍රමදාන ව්‍යාපාරය", "මහවැලි අධිකාරිය", "ශ්‍රී ලංකා ප්‍රමිති ආයතනය", "ජාතික විගණන කාර්යාලය", "ග්‍රාමීය ප්‍රජාවගේ ස්වයං-ශක්තිය හා සදාචාර දියුණුව පදනම් කරගත් සර්වෝදය ලෝක ප්‍රසිද්ධය."),
    q("ශ්‍රී ලාංකේය සමාජයේ ඈත අතීතයේ සිටම පැවති 'අත්තම සහ කයිය' වැනි සාමූහික වැඩ ක්‍රම මඟින් පිළිබිඹු වන්නේ කුමක්ද?", "ස්වේච්ඡා සහයෝගීතාව, ප්‍රජා සමගිය හා ශ්‍රමයේ ගෞරවය", "පෞද්ගලික ඒකාධිකාරය", "විදේශීය කම්කරු නීති", "වැටුප් කප්පාදුව", "මුදල් ගනුදෙනුවකින් තොරව ගමේ කෘෂිකාර්මික හා පොදු වැඩ එකමුතුවෙන් ඉටු කිරීම උසස් සිවිල් සංස්කෘතියකි."),
    q("රාජ්‍ය පාලනයේදී සිවිල් සමාජ සංවිධාන 'මුරකාර භූමිකාවක්' (Watchdog Role) ඉටු කරන ආකාරය කුමක්ද?", "මැතිවරණ නිරීක්ෂණය, මානව හිමිකම් සුරැකීම හා රාජ්‍ය මූල්‍ය විනිවිදභාවය අධීක්ෂණය කිරීම", "අමාත්‍ය මණ්ඩලය විසුරුවා හැරීම", "පොලිස් නිලධාරීන් පත් කිරීම", "බදු නීති අවලංගු කිරීම", "PAFFREL හා CMEV වැනි දේශීය මැතිවරණ නිරීක්ෂණ සංවිධාන නිදහස් හා සාධාරණ මැතිවරණ රැකීමට උපකාරී වේ."),
    q("සේවකයන්ගේ වැටුප්, සේවා කොන්දේසි හා වෘත්තීය අයිතිවාසිකම් ආරක්ෂා කර ගැනීමට පිහිටුවා ගන්නා සංවිධානය කුමක්ද?", "වෘත්තීය සමිතිය (Trade Union)", "පාරිභෝගික අධිකාරිය", "සමථ මණ්ඩලය", "මුදල් කොමිසම", "1935 අංක 14 වෘත්තීය සමිති ආඥාපනත යටතේ ශ්‍රී ලංකාවේ වෘත්තීය සමිති ලියාපදිංචි කර ක්‍රියාත්මක වේ."),
    q("වෘත්තීය සමිතිවලට පිවිසීමේ හා සංවිධානය වීමේ මූලික අයිතිවාසිකම 1978 ශ්‍රී ලංකා ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ කුමන වගන්තියෙන් සුරක්ෂිත කර ඇත්ද?", "14(1)(ඈ) වගන්තිය", "10 වගන්තිය", "12(4) වගන්තිය", "14(1)(ඌ) වගන්තිය", "සෑම පුරවැසියෙකුටම වෘත්තීය සමිති පිහිටුවීමේ හා ඒවාට බැඳීමේ නිදහස ව්‍යවස්ථාවෙන් තහවුරු කර ඇත."),
    q("වෘත්තීය සමිතියක් හා සේවායෝජකයා අතර වැටුප්, නිවාඩු හා සේවා කොන්දේසි පිළිබඳව සාමූහිකව සාකච්ඡා කර එකඟතාවයකට එළඹීම කුමක්ද?", "සාමූහික කේවල් කිරීම (Collective Bargaining)", "ඒකපාක්ෂික නෙරපීම", "බදු පැහැර හැරීම", "කම්හල වසා දැමීම (Lockout)", "ගැටුම් හා වැඩවර්ජන ඇතිවීමට පෙර සුහද සාකච්ඡාවෙන් කාර්මික සාමය ඇති කිරීමට සාමූහික කේවල් කිරීම උපකාරී වේ."),
    q("වැඩ ලෝකයේ කාර්මික ආරවුලක් විසඳීම සඳහා 'ජාත්‍යන්තර කම්කරු සංවිධානය' (ILO) අනුගමනය කරන ත්‍රෛපාර්ශ්වික (Tripartite) ව්‍යුහයේ සාමාජිකයන් තිදෙනා කවුද?", "රජය, සේවායෝජකයන් සහ සේවක (වෘත්තීය සමිති) නියෝජිතයන්", "පොලිසිය, හමුදාව සහ අධිකරණය", "බැංකු, රේගුව සහ පාසල්", "පළාත් සභා, ප්‍රාදේශීය සභා සහ නගර සභා", "1919 දී පිහිටුවූ ILO සංවිධානය වැඩ ලෝකයේ සමාජ සාධාරණත්වය රැකීමට මෙම පාර්ශ්ව තුනම එක් කරගනී."),
    q("සේවක අයිතිවාසිකම් හා සුබසාධනය නියාමනය කරන ශ්‍රී ලංකාවේ ප්‍රධාන රාජ්‍ය ආයතනය කුමක්ද?", "කම්කරු දෙපාර්තමේන්තුව", "විගණකාධිපති දෙපාර්තමේන්තුව", "පුරාවිද්‍යා දෙපාර්තමේන්තුව", "විභාග දෙපාර්තමේන්තුව", "කම්කරු කොමසාරිස් ජනරාල් යටතේ කම්කරු නීති ක්‍රියාත්මක කිරීම හා ආරවුල් සමථකරණය සිදු කෙරේ."),
    q("ශ්‍රී ලංකාවේ වෙළඳසැල් හා කාර්යාල සේවකයන්ගේ වැඩ කරන පැය ගණන, විවේකය, නිවාඩු හා වැටුප් පාලනය කරන ප්‍රධාන පනත කුමක්ද?", "සාප්පු හා කාර්යාල සේවක පනත (1954 අංක 19)", "සමථ මණ්ඩල පනත", "තොරතුරු දැනගැනීමේ පනත", "පළාත් සභා පනත", "සාමාන්‍යයෙන් දිනකට පැය 8 හා සතියකට පැය 45 උපරිම සේවා කාලය, අතිකාල ගෙවීම් හා නිවාඩු මෙයින් තහවුරු වේ."),
    q("රටේ ව්‍යවස්ථාපිත කම්කරු නීති යටතේ දරුවෙකු ලැබීමට සිටින සේවිකාවකට හිමිවන ප්‍රධාන සේවා අයිතිවාසිකම කුමක්ද?", "සම්පූර්ණ වැටුප් සහිත ප්‍රසූති නිවාඩු (Maternity Leave) හා රැකියා සුරක්ෂිතතාව", "සේවයෙන් පහ කිරීම", "වැටුප් අඩු කිරීම", "අනිවාර්ය රාත්‍රී සේවය", "මවගේ හා බිළිඳාගේ සෞඛ්‍යය ආරක්ෂා කිරීම සඳහා නීතියෙන් ප්‍රසූති නිවාඩු හා කිරි දීමේ විවේක ලබාදී ඇත."),
    q("පෞද්ගලික අංශයේ සේවකයෙකු එක් ආයතනයක අඛණ්ඩව වසර 5කට වැඩි කාලයක් සේවය කර ඉවත් වන විට හිමිවන මූල්‍ය ප්‍රතිලාභය කුමක්ද?", "පාරිතෝෂික දීමනාව (Gratuity - 1983 අංක 12 පනත)", "දඩ මුදල", "සමථ ගාස්තුව", "වරිපනම් බද්ද", "සේවකයාගේ දීර්ඝ කාලීන කැපවීම අගයමින් සෑම සම්පූර්ණ වසරකටම අවසන් වැටුපෙන් අඩ මාසයක වැටුප බැගින් ගෙවිය යුතුය."),
    q("1958 අංක 15 දරන සේවක අර්ථසාධක අරමුදල් (EPF) පනත යටතේ සේවකයා හා සේවායෝජකයා දායක මුදල් බැර කරන්නේ කුමන ප්‍රතිශතවලින්ද?", "සේවකයා අවම 8% සහ සේවායෝජකයා අවම 12% (මුළු 20%)", "දෙදෙනාම 1% බැගින්", "සේවකයා 50% සහ රජය 50%", "සේවායෝජකයා 0%", "ශ්‍රී ලංකා මහ බැංකුව මඟින් කළමනාකරණය කරන EPF අරමුදල සේවකයාගේ විශ්‍රාම ආරක්ෂණය සුරකී."),
    q("සේවා නියුක්තයන්ගේ භාර අරමුදල (ETF - 1980 අංක 46) සඳහා මාසිකව සම්පූර්ණ දායක මුදල (වැටුපෙන් 3%) ගෙවිය යුත්තේ කවුරුන් විසින්ද?", "සේවායෝජකයා විසින් පමණි (සේවකයාගේ වැටුපෙන් අඩු නොකර)", "සේවකයා විසින් පමණි", "ග්‍රාම නිලධාරී විසින්", "පාරිභෝගිකයන් විසින්", "EPF වෙනස් ලෙස ETF සඳහා සේවක වැටුපෙන් කිසිදු මුදලක් කපා නොගන්නා අතර සම්පූර්ණ 3% සේවායෝජකයා දරයි."),
    q("කර්මාන්තශාලා හා වැඩබිම්වල යන්ත්‍ර සූත්‍රවලින් සේවකයන්ට සිදුවන අනතුරු හා රෝග වැළැක්වීම සඳහා පිළිපැදිය යුතු අත්‍යවශ්‍ය ප්‍රමිතිය කුමක්ද?", "වෘත්තීය සෞඛ්‍යය හා ආරක්ෂාව (Occupational Health and Safety - OHS)", "වේගවත් වැඩකිරීම පමණක්", "නිවාඩු කප්පාදුව", "ආරක්ෂක උපකරණ ඉවත් කිරීම", "හිස්වැසුම්, අත්වැසුම්, ගිනි නිවන උපකරණ හා හොඳ වාතාශ්‍රය සැපයීම කර්මාන්තශාලා ආඥාපනත යටතේ අනිවාර්යය."),
    q("වැඩ ලෝකයේ 'සේවක අයිතිවාසිකම්' සේම සෑම සේවකයෙකු විසින්ම ආයතනය වෙනුවෙන් ඉටු කළ යුතු ප්‍රධාන යුතුකම කුමක්ද?", "නියමිත වේලාවට සේවයට පැමිණීම, අවංකව රාජකාරි කිරීම, ආයතන දේපළ රැකීම හා ගුණාත්මක සේවයක් සැලසීම", "සේවා කාලයේදී පෞද්ගලික වැඩ කිරීම", "රහස්‍ය දත්ත පිට කිරීම", "අමුද්‍රව්‍ය නාස්ති කිරීම", "සේවකයාගේ කැපවීම හා ආචාරධර්ම ආයතනයේ දියුණුවටත් තම රැකියා සුරක්ෂිතතාවටත් මුල් වේ."),
    q("ශ්‍රී ලංකාවේ 'විධිමත් අංශයේ' (Formal Sector) රැකියා සහ 'නොවිධිමත් අංශයේ' (Informal Sector) රැකියා වෙන් කරන ප්‍රධාන ලක්ෂණය කුමක්ද?", "විධිමත් අංශයේ ලිඛිත පත්වීම් ලිපි, ස්ථිර වැටුප්, EPF/විශ්‍රාම වැටුප් හා කම්කරු නීති ආරක්ෂාව පැවතීම", "නොවිධිමත් අංශයේ සියලු දෙනා රජයේ ඇමතිවරුන් වීම", "විධිමත් අංශයේ නිවාඩු නොමැති වීම", "නොවිධිමත් අංශයේ ඉහළ විශ්‍රාම වැටුප් තිබීම", "විධිමත් අංශය තුළ නීතිමය රැකියා සුරක්ෂිතතාව ඉහළ මට්ටමක පවතී."),
    q("අනාගත වැඩ ලෝකය සඳහා පාසල් සිසුන් තුළ වර්ධනය කළ යුතු 'මෘදු කුසලතා' (Soft Skills) ලෙස හැඳින්වෙන්නේ මොනවාද?", "සන්නිවේදන හැකියාව, කණ්ඩායම් හැඟීම, කාල කළමනාකරණය, ගැටලු විසඳීම හා නායකත්වය", "යන්ත්‍ර අලුත්වැඩියාව පමණක්", "කටපාඩම් කිරීම පමණක්", "තනිවම වැඩ කර කිසිවෙකුට කතා නොකිරීම", "තාක්ෂණික දැනුමට (Hard Skills) අමතරව මෘදු කුසලතා රැකියා සාර්ථකත්වය තීරණය කරයි."),
    q("වෘත්තීය ජීවිතයේදී 'ශ්‍රමයේ ගෞරවය' (Dignity of Labour) යන උදාර සංකල්පයෙන් කියැවෙන්නේ කුමක්ද?", "නීත්‍යානුකූල හා සමාජයට ප්‍රයෝජනවත් සෑම රැකියාවක්ම එක හා සමාන ගෞරවයෙන් සැලකිය යුතු බව", "කාර්යාල රැකියා පමණක් උසස් බව", "ශාරීරික ශ්‍රමය පහත් බව", "වැඩ නොකර ජීවත් වීම උසස් බව", "වෛද්‍යවරයාගේ සිට පවිත්‍රතා සේවකයා හා ගොවියා දක්වා සෑම දෙනාගේම ශ්‍රමය රටේ පැවැත්මට අත්‍යවශ්‍යය."),
    q("රටේ පුරවැසියන්ට 'රැකියාවක් තෝරාගැනීමේදී' සලකා බැලිය යුතු ප්‍රධාන පුද්ගලික හා සමාජීය සාධක මොනවාද?", "තම රුචිකත්වය, සහජ කුසලතා, අධ්‍යාපන/වෘත්තීය සුදුසුකම් හා වෙළඳපොළ ඉල්ලුම", "මිතුරන්ගේ කැමැත්ත පමණක්", "පෞද්ගලික ආචාරධර්ම නොසලකා හැරීම", "සුදුසුකම් නොමැතිව ඉහළම තනතුරු ඉල්ලීම", "නිවැරදි වෘත්තීය මාර්ගෝපදේශනය (Career Guidance) තෘප්තිමත් වැඩ ජීවිතයකට මග පාදයි."),
    q("ශ්‍රී ලංකාවේ තරුණ තරුණියන්ට ප්‍රායෝගික වෘත්තීය කුසලතා ලබාදීමට හඳුන්වා දී ඇති ජාතික සුදුසුකම් රාමුව කුමක්ද?", "NVQ (ජාතික වෘත්තීය සුදුසුකම් - National Vocational Qualification)", "GCE A/L කලා විෂය පමණක්", "SLS ප්‍රමිතිය", "RTI අංකය", "VTA, NAITA සහ ජර්මානු කාර්මික අභ්‍යාස ආයතන හරහා ලැබෙන NVQ සහතිකය දෙස් විදෙස් පිළිගැනීමට ලක්වේ."),
    q("රැකියා ස්ථානයක සේවකයන් අතර 'වැඩවර්ජනයක්' (Strike) යනු කුමක්ද?", "සාකච්ඡා අසාර්ථක වූ විට සේවකයන් සාමූහිකව සේවයෙන් ඉවත් වී තම ඉල්ලීම් දිනා ගැනීමට ගන්නා වෘත්තීය ක්‍රියාමාර්ගය", "රජයේ නිවාඩු දිනයක්", "සේවායෝජකයා විසින් කම්හල වැසීම (Lockout)", "ප්‍රසාද දීමනා බෙදාදීම", "අත්‍යවශ්‍ය සේවා හා මහජන ජීවිතයට අවම හානියක් වන ලෙස අවසන් පියවරක් ලෙස පමණක් මෙය භාවිත කෙරේ."),
    q("කාර්මික ආරවුල් විසඳීම සඳහා අධිකරණමය ක්‍රියාවලියෙන් පරිබාහිරව සේවකයන්ට පහසුවෙන් සහන ගත හැකි ශ්‍රී ලංකාවේ ආයතනය කුමක්ද?", "කම්කරු විනිශ්චය සභාව (Labour Tribunal) හා කම්කරු කොමසාරිස් සමථ ඒකකය", "සමථ මණ්ඩලය පමණක්", "පාරිභෝගික කටයුතු අධිකාරිය", "මැතිවරණ කොමිසම", "අසාධාරණ ලෙස සේවයෙන් පහ කළ සේවකයෙකුට මාස 6ක් ඇතුළත කම්කරු විනිශ්චය සභාවට අයදුම් කළ හැක."),
    q("විදේශ රැකියා සඳහා පිටත්ව යන ශ්‍රී ලාංකික ශ්‍රමිකයන්ගේ ආරක්ෂාව හා සුබසාධනය භාරව ක්‍රියා කරන රාජ්‍ය ආයතනය කුමක්ද?", "ශ්‍රී ලංකා විදේශ සේවා නියුක්ති කාර්යාංශය (SLBFE)", "ශ්‍රී ලංකා ප්‍රමිති ආයතනය", "මහවැලි අධිකාරිය", "පුරාවිද්‍යා දෙපාර්තමේන්තුව", "විදේශ රැකියා සඳහා ලියාපදිංචි වීම, පුහුණුව හා රක්ෂණ රැකවරණය ලබාගැනීමට SLBFE පිහිටුවා ඇත."),
    q("ශ්‍රම වෙළඳපොළේ 'විදේශගත ශ්‍රමිකයන් නීත්‍යානුකූල මාර්ගයෙන්ම විදේශගත වීම' වැදගත් වන්නේ ඇයි?", "මිනිස් ජාවාරම්වලින් බේරීමට, නිසි රැකියා ගිවිසුම් ලැබීමට හා රක්ෂණ ආරක්ෂාව හිමිවීමට", "වැඩි මුදලක් වංචාකරුවන්ට ගෙවීමට", "ගමන් බලපත්‍රය අහිමි කර ගැනීමට", "නීතිමය සහාය අහිමි කර ගැනීමට", "ලියාපදිංචි නොවූ අතරමැදියන් හරහා යාමෙන් ශ්‍රම සූරාකෑමට හා හිංසනයට ලක්වීමේ අවදානම වැඩිය."),
    q("රටේ සේවා ස්ථානවල 'ස්ත්‍රී පුරුෂ සමාන වැටුප් හා ලිංගික හිංසන වැළැක්වීම' වැදගත් වන්නේ ඇයි?", "සෑම සේවකයෙකුටම ආරක්ෂිත, ගෞරවාන්විත හා සමාන අවස්ථා සහිත වැඩ පරිසරයක් නිර්මාණය කිරීමට", "කාන්තාවන් රැකියාවලින් ඉවත් කිරීමට", "සේවක ඵලදායීතාව අඩු කිරීමට", "අධිකරණ වසා දැමීමට", "ශිෂ්ට සම්පන්න වැඩ ලෝකයක (Decent Work - SDG 8) සමාන වැඩට සමාන වැටුප් හා ආරක්ෂාව අනිවාර්ය වේ."),
    q("වැඩ ලෝකයේ 'වෘත්තීය ආචාරධර්ම' (Work / Professional Ethics) අනුගමනය කිරීමෙන් සේවකයාට ලැබෙන ප්‍රතිලාභය කුමක්ද?", "ආයතනික විශ්වාසය, වෘත්තීය ගෞරවය, උසස්වීම් හා මහජන ප්‍රසාදය දිනා ගැනීම", "සේවයෙන් නෙරපා හැරීම", "ගනුදෙනුකරුවන් අහිමි වීම", "විනය පරීක්ෂණ වැඩි වීම", "වෛද්‍යවරුන්, ගුරුවරුන්, ඉංජිනේරුවන් හා රාජ්‍ය සේවකයන් තම ආචාරධර්ම රැකීමෙන් සමාජයම සුරැකේ."),
    q("තම පවුලේ හෝ ප්‍රදේශයේ පාසල් සිසුන් සඳහා 'ස්වේච්ඡා සේවය' (Volunteerism) පුරුදු කිරීමෙන් තරුණ පරපුරට ලැබෙන පෞරුෂ වර්ධනය කුමක්ද?", "සහකම්පනය, නායකත්වය, සමාජ වගකීම හා ප්‍රජා බැඳීම් ශක්තිමත් වීම", "ආත්මාර්ථකාමීත්වය වැඩි වීම", "කාලය නාස්ති වීම පමණක්", "අනෙක් අය සමඟ ගැටුම් ඇති කර ගැනීම", "රතු කුරුස, බාලදක්ෂ, බාලදක්ෂිකා හා ප්‍රජා සේවා සමාජ සිවිල් පුරවැසිභාවය ප්‍රායෝගිකව පුහුණු කරයි."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක 'වෘත්තීය සංගම් හා විද්වත් සංවිධාන' (වෛද්‍ය, නීතිඥ හා ඉංජිනේරු සංගම් වැනි) සිවිල් සමාජයට දායක වන්නේ කෙසේද?", "ජාතික ප්‍රතිපත්ති පිළිබඳ විද්‍යාත්මක උපදෙස් දීමෙන් හා ප්‍රජාතන්ත්‍රවාදී අයිතීන් වෙනුවෙන් පෙනී සිටීමෙන්", "රෝහල් හා අධිකරණ වසා දැමීමෙන්", "විභාග අවලංගු කිරීමෙන්", "පුවත්පත් වාරණය කිරීමෙන්", "ශ්‍රී ලංකා නීතිඥ සංගමය (BASL) වැනි සංවිධාන නීතියේ ආධිපත්‍යය රැකීමට ප්‍රබල දායකත්වයක් දෙයි."),
    q("වැඩ ලෝකයේ 'නිදහස් හා නම්‍යශීලී රැකියා' (Freelancing / Remote Work) වර්තමානයේ ජනප්‍රිය වීමට බලපෑ ප්‍රධාන හේතුව කුමක්ද?", "අධිවේගී අන්තර්ජාලය, ඩිජිටල් මෙවලම් හා ගෝලීය තොරතුරු තාක්ෂණ සේවා වෙළඳපොළ පුළුල් වීම", "සියලු කර්මාන්තශාලා වැසී යාම", "විද්‍යුත් තැපෑල තහනම් වීම", "පරිගණක භාවිතය නතර වීම", "නිවසේ සිටම විදේශීය ව්‍යාපෘති සඳහා සේවා සපයා ඩොලර් ආදායම් ඉපයීමට තරුණයන්ට අවස්ථාව ලැබී ඇත."),
    q("රැකියාවක් ලබාගැනීමට අපේක්ෂා කරන පුද්ගලයෙකුගේ 'ජීවදත්ත පත්‍රිකාව' (CV / Resume) තුළ සෑමවිටම තිබිය යුතු ගුණාංගය කුමක්ද?", "අධ්‍යාපන සුදුසුකම්, කුසලතා හා අත්දැකීම් පැහැදිලිව හා අවංකව (සත්‍ය ලෙස) ඉදිරිපත් කිරීම", "ව්‍යාජ සහතික හා අසත්‍ය තොරතුරු ලිවීම", "පෞද්ගලික රහස් අංක ඇතුළත් කිරීම", "පිටු පනහක් දිගට ලිවීම", "සම්මුඛ පරීක්ෂණයකදී සත්‍යවාදී බව හා විශ්වසනීයත්වය පරීක්ෂා කෙරේ."),
    q("ශ්‍රී ලංකාවේ 'සේවා ස්ථාන ආරක්ෂණ කමිටු' මඟින් සේවකයන් හා කළමනාකාරිත්වය එක්ව සිදු කරන්නේ කුමක්ද?", "වැඩබිමේ අනතුරු අවදානම් හඳුනාගෙන හදිසි ඉවත් වීමේ පුහුණු හා ආරක්ෂිත පරිසරයක් පවත්වාගැනීම", "සේවක වැටුප් කප්පාදු කිරීම", "ආරක්ෂක හිස්වැසුම් තහනම් කිරීම", "නිවාඩු නතර කිරීම", "කාර්මික අනතුරු වළක්වා ගැනීම සඳහා පූර්ව ආරක්ෂණ ක්‍රමවේද අනුගමනය කිරීම ඉන් සිදුවේ."),
    q("සමාජ සේවා කටයුතුවල නියැලෙන 'සිවිල් සමාජ සංවිධානයකට' මහජන විශ්වාසය දිනා ගැනීම සඳහා අත්‍යවශ්‍ය වන්නේ කුමක්ද?", "මූල්‍ය විනිවිදභාවය, නිතිපතා විගණනය, දේශපාලන මධ්‍යස්ථභාවය හා ප්‍රතිලාභී වගවීම", "අරමුදල් රහසිගතව වියදම් කිරීම", "සියලු තොරතුරු සැඟවීම", "පක්ෂ ප්‍රචාරණය කිරීම", "මහජන හා විදේශීය ආධාර නිසි ලෙස ප්‍රජාවට ලැබෙන බව තහවුරු කිරීම සංවිධානයේ පැවැත්ම රකී."),
    q("ජාත්‍යන්තර කම්කරු සංවිධානය (ILO) අර්ථ දක්වන 'යහපත් රැකියාවක්' (Decent Work) යන්නට අයත් මූලිකාංග මොනවාද?", "සාධාරණ වැටුපක්, සුරක්ෂිත වැඩ පරිසරයක්, සමාජ ආරක්ෂණය හා වෘත්තීය සමිති නිදහස", "වැටුප් නොදී පැය 18ක් වැඩ ගැනීම", "ළමා ශ්‍රමය යෙදවීම", "වෙනස් කොට සැලකීම", "මිනිස් ගෞරවයට හා සංවර්ධනයට ඉඩ සලසන ඵලදායී රැකියාවක් Decent Work ලෙස සැලකේ."),
    q("වෘත්තීය සමිතියක් විසින් තම සාමාජිකයන්ගේ ගැටලු විසඳීමේදී 'නීත්‍යානුකූල හා සාමකාමී ක්‍රම' අනුගමනය කළ යුත්තේ ඇයි?", "පොදු දේපළ හා අනෙක් පුරවැසියන්ගේ මූලික අයිතිවාසිකම්වලට හානි නොවී මහජන සහාය රැකගැනීමට", "සමාජය තුළ අරාජිකත්වය වැඩි කිරීමට", "රෝහල් විදුලිය විසන්ධි කිරීමට", "ව්‍යාපාරික ස්ථාන කඩා දැමීමට", "රෝගීන්ගේ ජීවිත හා රටේ ආර්ථිකය නොසලකා හරින අරගල ජනතා ප්‍රසාදය අහිමි කර ගනී."),
    q("රැකියා ස්ථානයක 'ඵලදායීතාව' (Productivity) ඉහළ නැංවීම සඳහා සේවායෝජකයා හා සේවකයා අතර තිබිය යුතු සම්බන්ධතාව කුමක්ද?", "අන්‍යෝන්‍ය ගෞරවය, විවෘත සන්නිවේදනය, කුසලතා අගය කිරීම හා සාධාරණ ප්‍රතිලාභ බෙදාගැනීම", "බිය ගැන්වීම හා තර්ජනය කිරීම", "සේවක අදහස් නොසලකා හැරීම", "වැටුප් ගෙවීම ප්‍රමාද කිරීම", "තෘප්තිමත් සේවකයා වඩාත් නිර්මාණශීලීව ආයතනයේ සාර්ථකත්වයට දායක වේ."),
    q("පුද්ගලයෙකු වැඩ ලෝකයට පිවිසීමේදී 'ජීවිත කාලය පුරාම ඉගෙනීම' (Lifelong Learning) වැදගත් වන්නේ ඇයි?", "තාක්ෂණය හා වෘත්තීය අවශ්‍යතා වේගයෙන් වෙනස් වන බැවින් නව කුසලතා යාවත්කාලීන කර ගැනීමට", "පාසලෙන් පසු පොත් කියවීම තහනම් නිසා", "සියලු රැකියා අත්හැරීමට", "තාක්ෂණය භාවිත නොකිරීමට", "නිරන්තරයෙන් නව දැනුම ඉගෙන ගන්නා වෘත්තිකයා ඕනෑම ආර්ථික වෙනස්වීමකට සාර්ථකව මුහුණ දේ."),
    q("ශ්‍රී ලංකාවේ තරුණ ප්‍රජාව සිවිල් සමාජ කටයුතුවලට දායක වන ප්‍රධාන රාජ්‍ය හා ස්වේච්ඡා ව්‍යුහයක් කුමක්ද?", "යෞවන සමාජ (Youth Clubs), ශිෂ්‍ය පාර්ලිමේන්තු හා පරිසර සංගම්", "අධිකරණ සේවා කොමිසම", "රේගු දෙපාර්තමේන්තුව", "පාර්ලිමේන්තු විගණන කමිටුව", "ජාතික තරුණ සේවා සභාව හරහා දිවයින පුරා යෞවන සමාජ නායකත්වය හා ප්‍රජා සේවා දියුණු කරයි."),
    q("සේවකයෙකු විසින් රැකියා ගිවිසුමකට (Employment Contract) අත්සන් කිරීමේදී අනිවාර්යයෙන් පරීක්ෂා කළ යුතු කරුණු මොනවාද?", "තනතුර, වැටුප, වැඩ කරන පැය ගණන, නිවාඩු, EPF/ETF හා ඉවත් වීමේ දැනුම් දීමේ කාලය", "ආයතන ගොඩනැගිල්ලේ වර්ණය", "සේවායෝජකයාගේ උපන් දිනය", "ප්‍රචාරක දැන්වීම් සංඛ්‍යාව", "ලිඛිත පත්වීම් ලිපියක් තබාගැනීම කම්කරු අයිතිවාසිකම් රැකගැනීමේ පළමු පියවරයි."),
    q("ශ්‍රී ලංකාවේ 'අනිවාර්ය නොවන බලහත්කාරී ශ්‍රමය' (Forced Labour) තහනම් කර ඇත්තේ කුමන මූලික අයිතිවාසිකම හා නීතිය මගින්ද?", "මූලික මානව හිමිකම් හා ILO සම්මුති මගින් පුද්ගලයාගේ කැමැත්තෙන් තොරව බලෙන් වැඩ ගැනීම සපුරා තහනම් කිරීම", "රේගු පනත මගින් පමණක්", "වරිපනම් පනත මගින්", "පුවත්පත් මණ්ඩල පනත මගින්", "වහල් සේවය හා ණය බැඳීම් මත බලහත්කාරී ශ්‍රමය ලබාගැනීම මානව ගරුත්වයට සම්පූර්ණයෙන් පටහැනිය."),
    q("ජනමාධ්‍යය, වෘත්තීය සමිති සහ සිවිල් සමාජ සංවිධාන යන තුනම ඒකාධිපති පාලනයකදී මර්දනයට ලක්වන්නේ ඇයි?", "ඒවා මහජනතාව සංවිධානය කරමින් පාලකයන්ගේ වැරදි ප්‍රශ්න කරන ප්‍රබල ප්‍රජාතන්ත්‍රවාදී බලවේග වන බැවිනි", "ඒවා ආර්ථිකයට දායක නොවන නිසා", "ඒවාට කිසිදු සාමාජිකයෙකු නැති නිසා", "ඒවා පාසල් වැසීමට කටයුතු කරන නිසා", "නිදහස් සිවිල් සමාජයක් හා නිදහස් මාධ්‍යයක් ශක්තිමත් ප්‍රජාතන්ත්‍රවාදයක ජීව රුධිරය බඳුය."),
    q("රටේ රාජ්‍ය හා පෞද්ගලික අංශයේ සේවකයන් තුළ 'සමාජ වගකීම් සහගත වෘත්තීය හැසිරීමක්' ඇති කිරීමෙන් සමාජයට සිදුවන සේවය කුමක්ද?", "වංචාවෙන් තොර ගුණාත්මක සේවාවක් ජනතාවට ලැබී රටේ ජාත්‍යන්තර කීර්තිනාමය ඉහළ යාම", "කාර්යාල ප්‍රමාදයන් වැඩි වීම", "පාරිභෝගික පැමිණිලි දෙගුණ වීම", "නීති විරෝධී ගනුදෙනු වැඩි වීම", "සෑම රැකියාවක්ම මහජන සේවයක් ලෙස සලකා අවංකව ඉටු කිරීම දියුණු රාජ්‍යයක ලක්ෂණයකි."),
    q("පාසල් අධ්‍යාපනය නිම කර වැඩ ලෝකයට පිවිසෙන සිසුවෙකු සතු විය යුතු 'ඩිජිටල් හා තොරතුරු තාක්ෂණ කුසලතා' වැදගත් වන්නේ ඇයි?", "නවීන රැකියා සඳහා පරිගණක, අන්තර්ජාල, දත්ත විශ්ලේෂණ හා සයිබර් ආරක්ෂණ දැනුම අත්‍යවශ්‍ය වන බැවිනි", "කාර්යාල කඩදාසි වැඩි කිරීමට", "ලිපිගොනු සැඟවීමට", "අන්තර්ජාල පුවත් නොබලා සිටීමට", "තොරතුරු තාක්ෂණ සාක්ෂරතාව ඕනෑම ක්ෂේත්‍රයක රැකියා අවස්ථා පුළුල් කරයි."),
    q("සිවිල් සමාජ ක්‍රියාකාරකමකදී 'පෙත්සම් අත්සන් කිරීම හා මහජන සංවාද පැවැත්වීම' වැනි ප්‍රජාතන්ත්‍රවාදී ක්‍රමවේද භාවිත කිරීමේ වැදගත්කම කුමක්ද?", "සාමකාමී හා නීත්‍යානුකූල මාර්ගයෙන් පාලකයන්ගේ අවධානය දිනා ප්‍රතිපත්ති වෙනස් කිරීමට හැකි වීම", "ප්‍රචණ්ඩ ගැටුම් ආරම්භ කිරීම", "විදුලි රැහැන් කපා දැමීම", "රජයේ ගොඩනැගිලිවලට හානි කිරීම", "සිවිල් ප්‍රතිරෝධය හා උපදේශනය (Advocacy) නීතිගරුක සමාජයක වෙනස්කම් ඇති කිරීමේ ශිෂ්ට ක්‍රමයයි."),
    q("මාධ්‍ය හා සමාජ මාධ්‍ය ඔස්සේ සංවිධානය කෙරෙන 'සිවිල් ප්‍රජා ව්‍යාපාර' (පරිසර රැකීම හා ඩෙංගු මර්දනය වැනි) සාර්ථක වීමට හේතුව කුමක්ද?", "විශාල පිරිසකට ඉක්මනින් තොරතුරු සන්නිවේදනය වී සාමූහික දායකත්වය ලැබීම", "එය රහසිගතව සිදු කරන නිසා", "කිසිවෙකුට දැනුම් නොදෙන නිසා", "මාධ්‍ය වාරණය කර ඇති නිසා", "ජනමාධ්‍ය හා සිවිල් සමාජය අතර ධනාත්මක සම්බන්ධතාව සමාජ ප්‍රගතිය වේගවත් කරයි."),
    q("වැඩ ලෝකයේදී 'අවම වේතන නීතිය' (Minimum Wage Law) රජය විසින් පනවා ඇත්තේ කුමන අරමුණින්ද?", "ශ්‍රමිකයන් අඩු වැටුපට සූරාකෑම වැළැක්වී මූලික ජීවන අවශ්‍යතා සපුරා ගත හැකි අවම වැටුපක් තහවුරු කිරීමට", "සේවකයන්ට වැටුප් නොදී සිටීමට", "සියලු කර්මාන්තශාලා වැසීමට", "බදු අය කිරීම නතර කිරීමට", "2016 අංක 03 ජාතික අවම වේතන පනත මඟින් සේවකයාගේ ජීවන තත්ත්වය ආරක්ෂා කෙරේ."),
    q("ශ්‍රී ලංකාවේ 'පඩිපාලක සභා' (Wages Boards) පිහිටුවා ඇත්තේ කුමන කාර්යය ඉටු කිරීමටද?", "තේ, රබර්, ඇඟලුම්, ඉදිකිරීම් වැනි විවිධ කර්මාන්ත සඳහා අවම වැටුප්, නිවාඩු හා සේවා කොන්දේසි නියම කිරීමට", "පාසල් විභාග ප්‍රතිඵල නිකුත් කිරීමට", "පළාත් පාලන මැතිවරණ පැවැත්වීමට", "විදේශීය ණය ගැනීමට", "රජය, සේවායෝජකයන් හා සේවක සංගම් නියෝජිතයන්ගෙන් සැදුම්ලත් පඩිපාලක සභා 40කට අධික සංඛ්‍යාවක් ක්‍රියාත්මක වේ."),
    q("වෘත්තීය ජීවිතයේදී 'කාල කළමනාකරණය' (Time Management) හා 'විනිවිදභාවය' රැකීමෙන් රාජ්‍ය හා පෞද්ගලික ආයතනවලට අත්වන ප්‍රධාන වාසිය කුමක්ද?", "සේවා ප්‍රමාද අවම වී ආයතනයේ කාර්යක්ෂමතාව, මහජන විශ්වාසය හා ජාතික ඵලදායීතාව ඉහළ යාම", "ලිපිගොනු ගොඩගැසීම", "අල්ලස් ඉල්ලීම් වැඩි වීම", "සේවාදායකයන් අපහසුතාවට පත්වීම", "වගකීම්සහගත වැඩ සංස්කෘතියක් තුළින් පුද්ගලයාටත් රටටත් සමෘද්ධිය උදාවේ."),
    q("රැකියා ස්ථානයක සේවකයෙකු අතින් යම් අතපසුවීමක් සිදු වූ විට කළමනාකාරිත්වය ගත යුතු සාධාරණ විනය පියවර කුමක්ද?", "සේවකයාට කරුණු පැහැදිලි කිරීමට අවස්ථාව දී ස්වාභාවික යුක්තියට අනුව විධිමත් විනය පරීක්ෂණයක් පැවැත්වීම", "හේතු නොවිමසා එදිනම සේවයෙන් පහ කිරීම", "සේවකයාට ශාරීරික දඬුවම් දීම", "මුළු වැටුපම අහිමි කිරීම", "ස්වාභාවික යුක්ති මූලධර්මය අනුව විත්තිකරුට සවන් දීමෙන් පසු පමණක් තීරණ ගත යුතුය."),
    q("ශ්‍රී ලංකාවේ 'වැඩිහිටි, ළමා හා ආබාධිත ප්‍රජාව' වෙනුවෙන් පෙනී සිටින සිවිල් සමාජ සංවිධාන රටට කරන මෙහෙය කුමක්ද?", "රාජ්‍ය ප්‍රතිපත්තිවල අඩුපාඩු පෙන්වා දී සමාජ ආරක්ෂණය, ප්‍රවේශ පහසුකම් හා අධ්‍යාපනය ලබා ගැනීමට උපකාර කිරීම", "වැඩිහිටි නිවාස වසා දැමීම", "රාජ්‍ය සහනාධාර නතර කිරීම", "වෛද්‍ය සේවා ප්‍රතික්ෂේප කිරීම", "සිවිල් සමාජය ආන්තික ජන කොටස්වල හඬ බවට පත්වී සමානාත්මතාව තහවුරු කරයි."),
    q("වෘත්තීය සමිතියක ප්‍රධාන වගකීම් අතරට සේවක වැටුප් වැඩි කර ගැනීමට අමතරව අයත් වන වැදගත් කාර්යයක් කුමක්ද?", "වැඩබිම් ආරක්ෂාව තහවුරු කිරීම, සේවක අධ්‍යාපනය, සුබසාධනය හා කාර්යක්ෂමතාව වැඩි කිරීම", "කර්මාන්තශාලා විනාශ කිරීම", "සේවකයන්ගේ වැටුප් අඩු කිරීම", "කම්කරු නීති අවලංගු කිරීම", "වගකිවයුතු වෘත්තීය සමිති සේවක අයිතීන් සේම ආයතනයේ පැවැත්ම හා විනයද ආරක්ෂා කරයි."),
    q("ශ්‍රී ලංකාවේ පළමු වෘත්තීය සමිති ව්‍යාපාරය ගොඩනගා කම්කරු අයිතීන් වෙනුවෙන් සටන් කළ පුරෝගාමී නායකයා කවුද?", "ඒ.ඊ. ගුණසිංහ මහතා", "ඩොනමෝර් සාමිවරයා", "සෝල්බරි සාමිවරයා", "මැකලම් ආණ්ඩුකාරවරයා", "1920 දශකයේදී ඒ.ඊ. ගුණසිංහ මහතා ලංකා කම්කරු සංගමය පිහිටුවා වැඩ ලෝකයේ අයිතිවාසිකම් වෙනුවෙන් හඬ නැඟීය."),
    q("වැඩ ලෝකයේදී 'පරිවාස කාලය' (Probation Period) යනුවෙන් අදහස් කරන්නේ කුමක්ද?", "නව සේවකයෙකුගේ දක්ෂතාව හා කාර්යසාධනය ඇගයීමට ස්ථිර කිරීමට පෙර ලබාදෙන ආරම්භක සේවා කාලය", "විශ්‍රාම ගැනීමේ දිනය", "වැඩ වර්ජන කාලය", "අතිකාල වැටුප් ගෙවීම", "පරිවාස කාලය තුළ සේවකයාට ආයතන පරිසරයට හුරු වීමටත් ආයතනයට ඔහුගේ සුදුසුකම් තහවුරු කිරීමටත් හැකිවේ."),
    q("කර්මාන්තශාලා හා වැඩබිම්වල 'සාමූහික ගිවිසුමක්' (Collective Agreement) අත්සන් කිරීමේදී එය රජයේ කම්කරු කොමසාරිස් ලියාපදිංචි කරන්නේ ඇයි?", "සේවායෝජකයාට හා වෘත්තීය සමිතියට එම කොන්දේසි නීත්‍යානුකූලව බැඳී සිටීමට හා ආරවුල් වැළැක්වීමට", "එය පුළුස්සා දැමීමට", "බදු වැඩි කිරීමට", "සේවක නිවාඩු නැති කිරීමට", "ලියාපදිංචි සාමූහික ගිවිසුම් කාර්මික සාමය හා වැටුප් ස්ථාවරත්වය ආරක්ෂා කරයි."),
    q("ශ්‍රී ලංකාවේ 'වෘත්තීය මාර්ගෝපදේශනය' (Career Guidance) පාසල් සිසුන්ට වැදගත් වන්නේ ඇයි?", "විභාග ප්‍රතිඵල මත පමණක් නොව තම කුසලතා හා රැකියා වෙළඳපොළ අවස්ථා අනුව නිවැරදි වෘත්තියක් තෝරා ගැනීමට", "පාසල් අධ්‍යාපනය අතරමග නැවැත්වීමට", "එක් රැකියාවක් පමණක් බලෙන් කිරීමට", "තාක්ෂණික දැනුම අත්හැරීමට", "නිසි මාර්ගෝපදේශනය විරැකියාව අඩු කර රැකියා තෘප්තිය ඉහළ නංවයි."),
    q("වැඩ ලෝකයේදී 'තාක්ෂණික හා කාර්මික පුහුණු ආයතන' (NAITA, VTA හා UNIVOTEC වැනි) රටට වැදගත් වන්නේ කෙසේද?", "වෘත්තීය නිපුණතාවයෙන් යුත් කාර්මික, හෙද, සංචාරක හා තොරතුරු තාක්ෂණ ශ්‍රමිකයන් බිහි කිරීමෙන්", "සියලු කර්මාන්තශාලා වසා දැමීමෙන්", "පුහුණු ශ්‍රමිකයන් අඩු කිරීමෙන්", "විදේශ විනිමය නැවැත්වීමෙන්", "ප්‍රායෝගික වෘත්තීය අධ්‍යාපනය ජාතික සංවර්ධනයට අවශ්‍ය නිපුණ ශ්‍රම බලකාය සපයයි."),
    q("වෘත්තීය ජීවිතයේදී 'කණ්ඩායම් හැඟීම' (Teamwork) අත්‍යවශ්‍ය වන්නේ ඇයි?", "විවිධ දක්ෂතා ඇති සාමාජිකයන් එක්ව ක්‍රියා කිරීමෙන් සංකීර්ණ ඉලක්ක ඉක්මනින් හා සාර්ථකව සපුරා ගත හැකි බැවිනි", "අනෙක් අයගේ වැඩ කඩාකප්පල් කිරීමට", "තනිවම කිසිවෙකුට කතා නොකිරීමට", "ආයතනයේ සමගිය බිඳීමට", "සාර්ථක රෝහලක්, පාසලක් හෝ කර්මාන්තශාලාවක් පවතින්නේ කණ්ඩායම් සහයෝගීතාව මතය."),
    q("වැඩබිමේදී සේවකයෙකු 'මූල්‍ය හා තොරතුරු රහස්‍යභාවය' (Confidentiality) රැකිය යුත්තේ ඇයි?", "ආයතනයේ හා ගනුදෙනුකරුවන්ගේ පෞද්ගලික හා වාණිජ දත්ත වංචනිකයන් අතට පත් වීම වැළැක්වීමට", "තොරතුරු සියල්ල සමාජ මාධ්‍යයේ දැමීමට", "ගනුදෙනුකරුවන්ට පාඩු කිරීමට", "විගණකවරුන්ට බාධා කිරීමට", "බැංකු, රෝහල් හා තොරතුරු තාක්ෂණ සේවාවල රහස්‍යභාවය රැකීම ඉහළ වෘත්තීය ආචාරධර්මයකි."),
    q("සිවිල් සමාජයේ කොටසක් වන 'පාරිසරික ස්වේච්ඡා සංවිධාන' රටේ තිරසාර පැවැත්මට දායක වන ආකාරය කුමක්ද?", "වන රෝපණය, වෙරළ පිරිසිදු කිරීම, වනජීවීන් රැකීම හා පරිසර දූෂණයට එරෙහිව ජනතාව පෙළගැස්වීම", "වනාන්තර හෙළි කිරීම", "ප්ලාස්ටික් භාවිතය දෙගුණ කිරීම", "කසළ ගංගාවලට දැමීම", "සිවිල් පරිසර ක්‍රියාකාරීන්ගේ මැදිහත්වීම බොහෝ ස්වභාවික උරුමයන් විනාශ වීමෙන් බේරා ගෙන ඇත."),
    q("ශ්‍රී ලංකාවේ 'ගොවි සංවිධාන හා ධීවර සමිති' ග්‍රාමීය ප්‍රජාතන්ත්‍රවාදයේ වැදගත් කොටසක් වන්නේ ඇයි?", "වාරි ජලය බෙදාගැනීම, අස්වනු අලෙවිය හා ආපදා සහන පිළිබඳව ප්‍රජාව විසින්ම සාමූහික තීරණ ගන්නා බැවිනි", "වගාවන් සම්පූර්ණයෙන් නැවැත්වීමට", "වැව් විනාශ කිරීමට", "ධීවර රැකියාව තහනම් කිරීමට", "ගොවිජන සේවා පනත යටතේද ගොවි සංවිධානවලට නීතිමය පිළිගැනීමක් ලබාදී ඇත."),
    q("රැකියා ස්ථානයක සේවකයන්ගේ 'මානසික සුවය හා වැඩ-ජීවිත සමබරතාව' (Work-Life Balance) වැදගත් වන්නේ ඇයි?", "ආතතිය අඩු වී පවුල් ජීවිතය සතුටින් පවත්වාගනිමින් රැකියාවේ ගුණාත්මක බව ඉහළ යන බැවිනි", "සේවකයන් රෝගී වීමට", "නිවාඩු සම්පූර්ණයෙන් අහෝසි කිරීමට", "දිනකට පැය 20ක් වැඩ කිරීමට", "නිසි විවේකය හා වාර්ෂික නිවාඩු සේවක සෞඛ්‍යයටත් ආයතනයේ දිගුකාලීන ප්‍රගතියටත් හිතකරය."),
    q("වැඩ ලෝකයේදී 'සේවකයන් අතර වෙනස් කොට සැලකීම' (Workplace Discrimination) සිදු වන අවස්ථාවක් කුමක්ද?", "ජාතිය, ආගම, ස්ත්‍රී පුරුෂ භාවය හෝ ආබාධිත බව මත උසස්වීම් හා වැටුප් අහිමි කිරීම", "දක්ෂතාව මත උසස්වීම් දීම", "සේවා පළපුරුද්ද අගය කිරීම", "පුහුණු අවස්ථා සැමට දීම", "සමාන සුදුසුකම් ඇති සැමට සමාන අවස්ථා සැලසීම ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 12 වගන්තියට අනුකූලය."),
    q("ස්වේච්ඡා සේවය හා ප්‍රජා සත්කාරක සේවා (Community Service) සිදු කිරීමේදී තිබිය යුතු උසස්ම චේතනාව කුමක්ද?", "කිසිදු පෞද්ගලික ලාභයක් හෝ ප්‍රසිද්ධියක් නොතකා අවංකව අන් අයගේ යහපත සැලසීම", "අනෙක් අයගෙන් මුදල් කොල්ලකෑම", "පක්ෂ දේශපාලන ප්‍රචාරය කිරීම පමණි", "ආපදා ඡායාරූප විකිණීම", "සැබෑ පුරවැසි සේවය ගෞරවය හා සමාජ සංවේදීතාව මත පදනම් වේ."),
    q("ශ්‍රී ලංකාවේ 'සමුපකාර ව්‍යාපාරය' සිවිල් සමාජයේ හා ආර්ථිකයේ ශක්තිමත් ආදර්ශයක් වන්නේ කෙසේද?", "ප්‍රජාවගේ කුඩා ඉතිරි කිරීම් එකතු කර සාධාරණ පොලියට ණය හා සහන මිලට භාණ්ඩ සැපයීමෙන්", "විශාල පොලී අය කර පීඩා කිරීමෙන්", "භාණ්ඩ සඟවා විකිණීමෙන්", "සාමාජිකයන් බැහැර කිරීමෙන්", "විවිධ සේවා සමුපකාර සමිති, සණස හා ණය දෙන සමිති ග්‍රාමීය ප්‍රජාව බලගන්වා ඇත."),
    q("වෘත්තීය සමිති හා කළමනාකාරිත්වය අතර 'කාර්මික සාමය' (Industrial Peace) පවත්වාගැනීම රටේ ආර්ථිකයට වැදගත් වන්නේ ඇයි?", "නිෂ්පාදන බාධාවකින් තොරව පවත්වාගෙන යාමෙන් විදේශ ඇණවුම්, අපනයන ආදායම් හා සේවක වැටුප් රැකෙන බැවිනි", "කම්හල් සදාකාලිකව වැසීමට", "විදේශ ආයෝජකයන් පළවා හැරීමට", "වැටුප් ගෙවීම නැවැත්වීමට", "සේවකයන්ගේ සාධාරණ අයිතීන් සුරැකෙන විට නිරන්තර ගැටුම්වලින් තොරව ආයතන දියුණු වේ."),
    q("රටේ පුරවැසියන්ට 'රැකියා ස්ථානයක ආබාධ සහිත පුද්ගලයන්' සේවයේ යෙදවීමට ප්‍රතිපත්ති සකස් කළ යුත්තේ ඇයි?", "ඔවුන්ගේ කුසලතාවලට අවස්ථාව දී ස්වාධීනව ජීවත් වීමේ ගෞරවය හා සමානාත්මතාව තහවුරු කිරීමට", "ඔවුන් නිවෙස්වල සිර කර තැබීමට", "රැකියා පෝරම ප්‍රතික්ෂේප කිරීමට", "වැටුප් අහිමි කිරීමට", "රාජ්‍ය සේවයේ හා පෞද්ගලික අංශයේ ප්‍රවේශ පහසුකම් හා 3% කෝටා ප්‍රතිපත්ති ආබාධිත ප්‍රජාව සවිබල ගන්වයි."),
    q("පුද්ගලයෙකු 'ස්වයං රැකියාවක් හෝ කුඩා ව්‍යාපාරයක්' ආරම්භ කිරීමේදී පිළිපැදිය යුතු මූලික නීතිමය හා ප්‍රමිති පියවර කුමක්ද?", "ප්‍රාදේශීය සභාවේ වෙළඳ බලපත්‍රය ගැනීම, ප්‍රමිතිය රැකීම හා විධිමත් ගිණුම් තැබීම", "කිසිදු අනුමැතියකින් තොරව අපද්‍රව්‍ය පාරට දැමීම", "බාල අමුද්‍රව්‍ය යොදා පාරිභෝගිකයා රැවටීම", "බිල්පත් නොදීම", "නීත්‍යානුකූල ලියාපදිංචිය හා ගුණාත්මක බව ව්‍යාපාරයක් දිගුකාලීනව වර්ධනය වීමට අත්‍යවශ්‍යය."),
    q("වැඩ ලෝකයේදී 'විද්‍යුත් තැපෑලෙන් හා මාර්ගගතව රැකියා සෙවීමේදී' පුද්ගලයන් සැලකිලිමත් විය යුතු ආරක්ෂණ කරුණ කුමක්ද?", "ව්‍යාජ විදේශ රැකියා දැන්වීම්වලට මුදල් නොගෙවා නිල ආයතන හරහා සත්‍යතාව පරීක්ෂා කිරීම", "නාඳුනන පුද්ගලයන්ට ගමන් බලපත්‍රය තැපැල් කිරීම", "රහස් බැංකු අංක ලබා දීම", "විමසීමකින් තොරව මුදල් බැර කිරීම", "අන්තර්ජාල රැකියා වංචාවලින් බේරීමට විදේශ සේවා නියුක්ති කාර්යාංශයේ නිල ලැයිස්තු පරීක්ෂා කළ යුතුය."),
    q("සිවිල් සමාජ සංවිධාන විසින් 'ජාතික හා ප්‍රාදේශීය ආපදා අවස්ථාවලදී' සිදු කරන කැපී පෙනෙන සේවය කුමක්ද?", "රජයේ හමුදා හා ආපදා මධ්‍යස්ථාන සමඟ එක්ව වියළි ආහාර, ජලය, ඇඳුම් හා ප්‍රථමාධාර සැපයීම", "සහන බෙදාදීමට බාධා කිරීම", "අසත්‍ය බිය පැතිරවීම", "පාරවල් වසා දැමීම", "රතු කුරුස සමාජය, සර්වෝදය හා ගමේ සමිති සමාගම් ආපදාවලදී ප්‍රථමයෙන් ඉදිරිපත් වේ."),
    q("රටේ වෘත්තීය අධ්‍යාපන පද්ධතිය තුළ 'ආධුනිකත්ව පුහුණුව' (Apprenticeship / On-the-Job Training) වැදගත් වන්නේ ඇයි?", "පන්ති කාමර න්‍යායට අමතරව සැබෑ කර්මාන්තශාලා හා වැඩබිම් අත්දැකීම් ශිෂ්‍යයාට ලැබෙන බැවිනි", "සිසුන්ට කිසිවක් ඉගෙනීමට නොලැබෙන බැවින්", "කාලය නාස්ති කිරීමට", "ප්‍රායෝගික පුහුණුව තහනම් කිරීමට", "වැඩ ලෝකයේ සැබෑ අභියෝගවලට මුහුණ දීමට සිසුන් සූදානම් කිරීම ආධුනිකත්ව පුහුණුවේ අරමුණයි."),
    q("රැකියාවක් කරන අතරතුර 'අනවශ්‍ය නාස්තිය වැළැක්වීම' (විදුලිය, ජලය හා කඩදාසි ආදියෙහි) සේවකයාගේ යුතුකමක් වන්නේ ඇයි?", "ආයතනයේ වියදම් අඩු වී ලාභදායීතාව හා පාරිසරික තිරසාරභාවය රැකෙන බැවිනි", "ආයතනය බංකොලොත් කිරීමට", "විදුලි බිල වැඩි කිරීමට", "කසළ ගොඩගැසීමට", "ආයතනික සම්පත් තම පෞද්ගලික දේපළ මෙන් පරිස්සමින් පාවිච්චි කිරීම උසස් වැඩ සංස්කෘතියකි."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක 'සාමකාමී පෙළපාලියක් හෝ උද්ඝෝෂණයක්' පවත්වන විට වෘත්තීය සමිති හා සිවිල් කණ්ඩායම් පිළිපැදිය යුතු සීමාව කුමක්ද?", "පොදු දේපළවලට හානි නොකිරීම, ගිලන් රථ හා රෝගීන්ට බාධා නොකිරීම හා ප්‍රචණ්ඩ නොවීම", "වාහන ගිනි තැබීම", "පාසල් දරුවන්ට හිරිහැර කිරීම", "පොදු බස් රථ කැඩීම", "ව්‍යවස්ථාවේ 14(1)(ආ) වගන්තියෙන් පිළිගෙන ඇත්තේ 'සාමකාමීව හා ආයුධ රහිතව රැස්වීමේ නිදහස' පමණි."),
    q("ශ්‍රී ලංකාවේ 'වැඩිහිටි ජනගහනය වේගයෙන් ඉහළ යාම' (Ageing Population) අනාගත වැඩ ලෝකයට හා සමාජ ආරක්ෂණයට බලපාන්නේ කෙසේද?", "විශ්‍රාම වැටුප්, වැඩිහිටි සෞඛ්‍ය සේවා ශක්තිමත් කිරීමට හා තරුණ ශ්‍රම ඵලදායීතාව වැඩි කිරීමට සිදුවීම", "පාසල් සියල්ල වැසී යාමට", "වැඩිහිටියන්ට සෞඛ්‍ය සේවා නැවැත්වීමට", "EPF අරමුදල වසා දැමීමට", "දකුණු ආසියාවේ වේගයෙන්ම වයස්ගත වන ජනගහනයක් සිටින රටක් ලෙස ශ්‍රී ලංකාව සමාජ ආරක්ෂණය සැලසුම් කළ යුතුය."),
    q("වෘත්තීය ජීවිතයේදී 'සේවක-සේවායෝජක සංහිඳියාව' වර්ධනය කිරීමට ආයතන තුළ පිහිටුවා ගන්නා ඒකාබද්ධ මණ්ඩල කුමක්ද?", "සේවක සභා හෙවත් ඒකාබද්ධ උපදේශන කමිටු (Joint Consultative Committees)", "අපරාධ අධිකරණ", "පළාත් සභා කමිටු", "විභාග මණ්ඩල", "ආරවුලක් වර්ජනයක් දක්වා දුරදිග යාමට පෙර ආයතනය තුළම සාකච්ඡාවෙන් විසඳීමට මෙම කමිටු ක්‍රියා කරයි."),
    q("රටේ තරුණ පරපුරට 'සමාජ ව්‍යවසායකත්වය' (Social Entrepreneurship) හඳුන්වා දීමේ විශේෂ වටිනාකම කුමක්ද?", "ව්‍යාපාරික ආදායම් උපයන අතරම පරිසර දූෂණය හෝ ග්‍රාමීය දිළිඳුකම වැනි සමාජ ගැටලුවලට විසඳුම් දීම", "ලාභය පමණක් ගෙන සේවකයන් සූරාකෑම", "පරිසර නීති කඩ කිරීම", "සමුපකාර සමිති වැසීම", "උදාහරණයක් ලෙස ග්‍රාමීය කාන්තාවන් එක් කර පරිසර හිතකාමී ඇසුරුම් නිපදවා අලෙවි කිරීම සමාජ ව්‍යවසායකත්වයකි."),
    q("සිවිල් සමාජයේ ක්‍රියාකාරී සාමාජිකයෙකු වීමට පාසල් ශිෂ්‍යයෙකුට දැන් සිටම සම්බන්ධ විය හැකි පාසල් සංගම් මොනවාද?", "පරිසර නියමු බලකාය, ශිෂ්‍ය පාර්ලිමේන්තුව, බාලදක්ෂ ව්‍යාපාරය හා ශාන්ත ජෝන් ගිලන් රථ බලකාය", "කළුකඩ වෙළඳ සංගම්", "පෞද්ගලික මුදල් පොලී සංගම්", "ව්‍යාජ පුවත් කණ්ඩායම්", "විෂය බාහිර ක්‍රියාකාරකම් සිසුන් තුළ සාමූහිකත්වය, විනය හා සේවා කැපවීම ගොඩනඟයි."),
    q("වැඩ ලෝකයේ 'කම්කරු නීති උල්ලංඝනයක්' (වැටුප් නොගෙවීම හෝ EPF නොදැමීම වැනි) සිදු වූ විට සේවකයාට පැමිණිලි කළ හැක්කේ කා වෙතද?", "ප්‍රාදේශීය කම්කරු කාර්යාලය සහ කම්කරු කොමසාරිස් ජනරාල් වෙත", "විභාග දෙපාර්තමේන්තුවට", "පුරාවිද්‍යා දෙපාර්තමේන්තුවට", "පාරිභෝගික අධිකාරියට", "කම්කරු පරීක්ෂකවරුන් විසින් වැඩබිම් පරීක්ෂා කර සේවකයන්ට හිමි නීත්‍යානුකූල මුදල් අය කර දීමට කටයුතු කරයි."),
    q("වෙළඳපොළ තරගකාරිත්වය මැද වෘත්තීයවේදියෙකු තුළ තිබිය යුතු 'ප්‍රතිපත්තිගරුක බව' (Integrity) යනු කුමක්ද?", "කිසිවෙකු බලා නොසිටින අවස්ථාවක පවා අල්ලස් නොගෙන අවංකව හා සාධාරණව රාජකාරි කිරීම", "මුදල් ලැබෙන පැත්තට වාර්තා වෙනස් කිරීම", "පෞද්ගලික වාසියට රජයේ රහස් විකිණීම", "කාර්යාල උපකරණ ගෙදර ගෙන යාම", "සදාචාරාත්මක අවංකභාවය රැකියා ලෝකයේත් සිවිල් සමාජයේත් ඉහළම පෞරුෂ ලක්ෂණයයි."),
    q("රටේ සියලු පුරවැසියන්ට 'විධිමත් හා සුරක්ෂිත වැඩ ලෝකයක්' බිහි වීමෙන් සමාජයට සිදුවන යහපත කුමක්ද?", "පවුල් ආර්ථිකය ශක්තිමත් වීම, දිළිඳුකම අඩු වීම, සමාජ සාමය රැකීම හා ජාතික ආදායම ඉහළ යාම", "විරැකියාව වැඩි වීම", "ළමා ශ්‍රමය ඉහළ යාම", "අධ්‍යාපනය අඩාල වීම", "සේවකයා, සේවායෝජකයා හා රජය අතර සාධාරණ සහයෝගීතාව සමෘද්ධිමත් රටක පදනමයි."),
    q("ශ්‍රී ලංකාවේ මහජන මතය, නිදහස් ජනමාධ්‍ය, වෘත්තීය සමිති හා සිවිල් සමාජය ආරක්ෂා කිරීමේ අවසාන වගකීම ඇත්තේ කාටද?", "ප්‍රජාතන්ත්‍රවාදය අගය කරන සෑම සවිඥානික පුරවැසියෙකුටම හා ව්‍යවස්ථාපිත රාජ්‍ය ආයතනවලට", "විදේශීය හමුදාවලට පමණි", "තනි පුද්ගලයෙකුට පමණි", "රේගු නිලධාරීන්ට පමණි", "විමසිලිමත් හා සක්‍රීය පුරවැසියන් සිටින තාක් කල් කිසිදු ඒකාධිපති බලවේගයකට ප්‍රජාතන්ත්‍රවාදය යටපත් කළ නොහැක.")
  )
}

